<script setup lang="ts">
const db=useDb(),w=useWorkspace(),form=ref<any>({...w.value}),{error,busy,notice,run}=useAction(),owner=ref(false)
const {data}=await db.auth.getUser();owner.value=!!check(await db.from('quolyn_workspace_members').select('role').eq('workspace_id',w.value!.id).eq('user_id',data.user!.id).single())?.role.match(/^owner$/)
async function save(){await run(async()=>{const {id,created_at,...p}=form.value;check(await db.from('quolyn_workspaces').update(p).eq('id',w.value!.id));w.value={...form.value};notice.value='Workspace settings saved'})}
async function logo(e:Event){await run(async()=>{const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;if(!['image/png','image/jpeg'].includes(file.type)||file.size>2097152)throw new Error('Use PNG or JPEG under 2 MB');const path=`${w.value!.id}/${crypto.randomUUID()}.${file.type==='image/png'?'png':'jpg'}`;check(await db.storage.from('workspace-assets').upload(path,file));form.value.logo_path=path;notice.value='Logo uploaded. Save settings to use it.'})}
async function demo(){await run(async()=>{if(!window.confirm('Add fictional Northfield demo products and Oakline customer to this workspace? Existing records are preserved.'))return;await $fetch('/api/demo',{method:'POST'});notice.value='Fictional demo catalogue, customer and two enquiries added. Open Enquiries to begin.'})}
</script>
<template><div><div class="page-title"><div><div class="eyebrow">WORKSPACE PREFERENCES</div><h1>Settings</h1><p>Business identity, commercial defaults and pilot tools.</p></div></div><p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert success">{{notice}}</p><form class="panel" @submit.prevent="save"><h2>Distributor identity</h2><fieldset :disabled="!owner||busy" style="border:0;padding:0"><div class="form-grid"><label>Business name<input v-model="form.name" required></label><label>Logo (PNG / JPEG)<input type="file" accept="image/png,image/jpeg" @change="logo"></label></div><label>Business address<textarea v-model="form.address"></textarea></label><div class="form-grid"><label>Default currency<select v-model="form.currency"><option v-for="c in ['INR','USD','EUR','GBP','AED','JPY','KWD']" :key="c">{{c}}</option></select></label><label>Default tax basis points<input v-model.number="form.tax_bps" type="number" min="0" max="10000" placeholder="Unknown"></label><label>Quote prefix<input v-model="form.quote_prefix" required maxlength="20"></label><label>Validity (days)<input v-model.number="form.validity_days" type="number" min="1" max="365"></label><label>Discount warning threshold (bps)<input v-model.number="form.discount_warning_bps" type="number" min="0" max="10000"></label><label>Margin warning threshold (bps)<input v-model.number="form.margin_warning_bps" type="number" min="0" max="10000"></label></div><label>Terms and conditions<textarea v-model="form.terms"></textarea></label><button class="primary" :disabled="busy">Save settings</button></fieldset><p v-if="!owner" class="muted">Only the workspace owner can change these settings.</p></form><div class="panel"><h2>Enquiry analysis</h2><span class="pill confirmed">Deterministic mode available</span><p class="muted">Optional AI requires server-side provider configuration. Credentials are never entered in this workspace. Analysis failures remain visible, and manual review is always available.</p></div><div class="panel"><h2>Explore with fictional data</h2><p class="muted">Add 30 Northfield Surfaces products, Oakline Interiors, and two example enquiries. All names, specifications and prices are fictional.</p><button class="secondary" :disabled="busy" @click="demo">Load fictional demo data</button></div></div></template>
